enum PaginationStatus { initial, loading, ready, loadingMore, refreshing, endOfList, error }
class PaginationState<T>{const PaginationState({this.items=const[],this.status=PaginationStatus.initial,this.nextPageToken,this.error});final List<T> items;final PaginationStatus status;final String? nextPageToken;final Object? error;PaginationState<T> copyWith({List<T>? items,PaginationStatus? status,String? nextPageToken,Object? error})=>PaginationState(items:items??this.items,status:status??this.status,nextPageToken:nextPageToken??this.nextPageToken,error:error);}
class MockPaginator<T>{MockPaginator(this.source,{this.pageSize=10,Object Function(T)? idOf}):idOf=idOf??((item)=>item as Object);final List<T> source;final int pageSize;final Object Function(T) idOf;PaginationState<T> state=const PaginationState();bool _loading=false;Future<PaginationState<T>> loadInitial()async{if(_loading)return state;_loading=true;state=const PaginationState(status:PaginationStatus.loading);try{return _page(0);}finally{_loading=false;}}Future<PaginationState<T>> loadMore()async{if(_loading||state.status==PaginationStatus.endOfList)return state;_loading=true;state=state.copyWith(status:PaginationStatus.loadingMore);try{return _page(int.tryParse(state.nextPageToken??'')??state.items.length);}finally{_loading=false;}}Future<PaginationState<T>> refresh()=>loadInitial();PaginationState<T> _page(int start){final end=(start+pageSize).clamp(0,source.length) as int;final page=source.sublist(start,end);final seen={for(final item in state.items)idOf(item)};final combined=start==0?<T>[]:[...state.items];for(final item in page){if(seen.add(idOf(item)))combined.add(item);}return state=PaginationState(items:combined,status:end==source.length?PaginationStatus.endOfList:PaginationStatus.ready,nextPageToken:end==source.length?null:'$end');}}
